Patterns courants :
// Interface vs Type
interface User { id: number; name: string; email?: string }
type Status = 'active' | 'inactive' | 'pending'

// Générique
function pick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  return keys.reduce((acc, k) => ({ ...acc, [k]: obj[k] }), {} as Pick<T, K>)
}

// Utility types
type PartialUser = Partial<User>        // toutes les props optionnelles
type UserPreview = Pick<User, 'id' | 'name'>  // sous-ensemble
type UserWithoutEmail = Omit<User, 'email'>   // sans email

// Null safety
function greet(name: string | null) {
  if (!name) return 'Bonjour'
  return `Bonjour ${name}`
}

Hooks essentiels :
// useState
const [count, setCount] = useState(0)

// useEffect (fetch au montage)
useEffect(() => {
  fetch('/api/data').then(r => r.json()).then(setData)
}, [])  // [] = une seule fois

// useEffect avec dépendance
useEffect(() => {
  document.title = `${count} nouveaux messages`
}, [count])  // relancé quand count change

// Custom hook réutilisable
function useFetch<T>(url: string) {
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(true)
  useEffect(() => {
    fetch(url).then(r => r.json()).then(d => { setData(d); setLoading(false) })
  }, [url])
  return { data, loading }
}

